import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { en } from '../locales/en';
import { hi } from '../locales/hi';
import { bn } from '../locales/bn';
import { ui } from '../locales/ui';

export type SupportedLanguage = 'en' | 'hi' | 'bn';

const translations: Record<SupportedLanguage, any> = {
  en,
  hi,
  bn
};

interface LanguageContextType {
  language: SupportedLanguage;
  setLanguage: (lang: SupportedLanguage) => void;
  t: (key: string, fallback?: string) => string;
  translate: (text: string) => string;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

const STORAGE_KEY = 'setu_language';

export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [language, setLanguageState] = useState<SupportedLanguage>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved && (saved === 'en' || saved === 'hi' || saved === 'bn')) {
      return saved as SupportedLanguage;
    }
    return 'en';
  });

  const setLanguage = (lang: SupportedLanguage) => {
    setLanguageState(lang);
    localStorage.setItem(STORAGE_KEY, lang);
    document.documentElement.lang = lang;
  };

  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  const translate = (text: string): string => {
    if (language === 'en') return text;
    const key = text.replace(/\s+/g, ' ').trim().toLowerCase();
    const translated = ui[key]?.[language];
    return translated ? text.replace(text.trim(), translated) : text;
  };

  // Nested object lookup helper e.g. t('nav.circuits')
  const t = (keyPath: string, fallback?: string): string => {
    const keys = keyPath.split('.');
    let currentDict = translations[language] || translations.en;
    let fallbackDict = translations.en;

    let result: any = currentDict;
    for (const k of keys) {
      if (result && typeof result === 'object' && k in result) {
        result = result[k];
      } else {
        result = undefined;
        break;
      }
    }

    if (result && typeof result === 'string') {
      return result;
    }

    // Fallback to English dictionary if key missing in selected language
    let fbResult: any = fallbackDict;
    for (const k of keys) {
      if (fbResult && typeof fbResult === 'object' && k in fbResult) {
        fbResult = fbResult[k];
      } else {
        fbResult = undefined;
        break;
      }
    }

    if (fbResult && typeof fbResult === 'string') {
      return translate(fbResult);
    }

    return translate(fallback || keyPath);
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t, translate }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useTranslation = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useTranslation must be used within a LanguageProvider');
  }
  return context;
};
